import{_ as l,l as o,o as e,c as s,v as r,p as n,x as t,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"中频粗糙 MSFR","description":"","frontmatter":{"title":"中频粗糙 MSFR","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/msfr.md","filePath":"litho/msfr.md","lastUpdated":1789023840000}'),S={name:"litho/msfr.md"};function f(m,a,u,E,c,A){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="中频粗糙-msfr" tabindex="-1">中频粗糙 MSFR <a class="header-anchor" href="#中频粗糙-msfr" aria-label="Permalink to &quot;中频粗糙 MSFR&quot;">​</a></h1><div class="epigraph"><p>MSFR 夹在面形与高频抛光之间：空间波长从毫米落到微米。它既不像 Zernike 那样好补偿，也不会全部进大角度 TIS。</p><footer>—— 据 Zeiss 对 MSFR 分频；Gullikson 散射与小角度晕</footer></div><p><a href="/litho/mirror-figure-error">上一课</a>把低频面形收进波前。缺口是中间那一档：mid-spatial frequency roughness（MSFR）。抛光和镀膜最容易在这里留下「既不像像差、又不像雾」的晕。能量预算如何被镜面张数再乘一次，留给<a href="/litho/reflectivity-mirror-count">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>面形可以用刚体装调和少量能动补偿。高频主要掉峰值 \\(R\\)、喂大角度散射。MSFR 对应的散射角把能量送到邻近视场点：局部 flare、条纹状对比损失、以及与图形密度相关的中程底座。Kirk 全场积分会把它和高频 TIS 混在一个百分数里，OPC 若只用 DC flare，会修错空间尺度。</p><p>缺口是给这档频率单独建桶，而不是再用一个 RMS。收集镜溅射坑的相关长度往往落在中频；投影镜则看抛光纹和镀膜复制。功率清洗课的不可逆项，很大一块以 MSFR 的形式进入投影链。</p><p><span class="marginnote">分频边界没有国际法定值，工程上按「可补偿像差 / 中程晕 / 大角度 TIS」切。写规格必须同时写空间波长窗口，不能只写「MSFR \\(\\lt\\) x nm」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计量：白光或 EUV 散射、子孔径干涉、原子力显微镜，覆盖不同空间频段，拼成 PSD。规格按频带积分的 RMS 或按 PSD 包络。镀膜后复测：多层会滤波或复制基底 MSFR，相关界面让中频散射增强。</p><p>计算光刻：把中程核从长程 flare 里拆出来，核宽度对应 MSFR 散射角在硅片上的尺度（数十到数百微米量级，随 NA 与光学布局变）。换光瞳时照射足迹变，有效 MSFR 贡献会变，SMO 要重评估，不能只重算标称 TCC。</p><h3 id="抛光纹的各向异性" tabindex="-1">抛光纹的各向异性 <a class="header-anchor" href="#抛光纹的各向异性" aria-label="Permalink to &quot;抛光纹的各向异性&quot;">​</a></h3><p>离子束或机械抛光常留下优势方向。MSFR 因此不是各向同性晕：某一方向的中程底座更强，密集线与垂直线的 PV-band 差会像「照明不对称」。先查镜子 PSD 的方位，再改极子。收集镜溅射坑较随机，投影镜抛光纹较定向，两面的中程核形状不同。</p>',12)),(e(),n(p,null,{default:t(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIG%5B%22Figure%20%E4%BD%8E%E9%A2%91%22%5D%20--%3E%20COMP%5B%22%E8%A3%85%E8%B0%83%E5%8F%AF%E8%A1%A5%E5%81%BF%22%5D%0A%20%20MSFR%5B%22MSFR%20%E4%B8%AD%E9%A2%91%22%5D%20--%3E%20HALO%5B%22%E4%B8%AD%E7%A8%8B%E6%99%95%20%2F%20%E5%B1%80%E9%83%A8%20flare%22%5D%0A%20%20HSFR%5B%22HSFR%20%E9%AB%98%E9%A2%91%22%5D%20--%3E%20TIS%5B%22%E5%A4%A7%E8%A7%92%E5%BA%A6%20TIS%20%2F%20%E6%8E%89%20R%22%5D%0A%20%20HALO%20--%3E%20OPC%5B%22%E9%9C%80%E4%B8%AD%E7%A8%8B%E6%A0%B8%20%E9%9D%9E%20DC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>散射角 \\(\\theta_s \\sim \\lambda f\\)，其中 \\(f\\) 是表面空间频率。13.5 nm 下，毫米⁻¹ 到微米⁻¹ 的 \\(f\\) 把光送到视场内可观的距离，却仍可能落在光瞳里被当成「像的一部分」。于是 MSFR 表现为像质退化而不是纯粹杂散：NILS 掉、孤立线和密集线的偏置差加大。这与 <a href="/litho/euv-flare-ml">EUV flare</a> 课的「中频把能量送到几十到几百微米」是同一物理，本课把它标成镜子出厂与运行必须单独管的频段。</p><p>氢致起泡、帽层粗化会在运行中抬 MSFR。收集镜更明显；投影镜一旦中频变差，通常没有原位「抛光」，只能防污染和控热。</p><p><span class="marginnote">不要把 MSFR 写成「比 figure 差一点的抛光」。补偿手段不同：一边是刚体，一边几乎只能在制造阶段杀掉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把六镜透过率乘积算完，下一课才把 \\(R^N\\) 写成功率预算。不重写 Kirk 实验步骤。MSFR 规格必须带空间频率窗口，一个 RMS 会把面形和高频误并进同一桶。出处：Zeiss MSFR；Gullikson PSD–散射；Naulleau；Bakshi 光学公差。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MSFR 是中频高度误差，产生中程晕，装调补不掉。</li><li>规格必须带空间频率窗口；运行污染会抬这一档。</li><li>下一课：在面形和粗糙都已被分段之后，反射率与镜数如何规定光源。</li><li>出处：Zeiss；Gullikson；Naulleau；Bakshi。</li></ul>',8))])}const F=l(S,[["render",f]]);export{R as __pageData,F as default};
